style.css:
@-moz-document domain("discord.com") {
/* 1. Make the main app container transparent so the background shows through */
    #app-mount, 
    [class^="app_"], 
    [class^="bg_"], 
    [class^="container_"], 
    [class^="chat_"], 
    [class^="sidebar_"], 
    [class^="panels_"],
    [class^="scroller_"],
    [class^="pageWrapper_"] {
        background: transparent !important;
        background-color: transparent !important;
    }   

    /* 2. Apply your custom wallpaper to the main body */
    body {
        background-image: url("https://images-wixmp-ed30a86b8c4ca887773594c2.wixmp.com/f/1cc3a7fd-19bc-45f5-abd3-ffc706bf7f0b/d6gzw2c-514c768c-3375-441f-be95-8d9eb1ac7db8.png?token=eyJ0eXAiOiJKV1QiLCJhbGciOiJIUzI1NiJ9..fyew4L8bXO918_pfT6_Ut8cHZ3AA711KPeudWpgkig0") !important;
        background-size: cover !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
        background-attachment: fixed !important;
    }

    /* 3. Optional: Add a dark translucent overlay so text remains readable */
    [class^="chat_"]::before {
        content: "";
        position: absolute;
        inset: 0;
        background: rgba(0, 0, 0, 0.4); /* Adjust 0.4 to change opacity */
        pointer-events: none;
        z-index: 0;
    }
}
